        attempt: attempt,
        ignoreErrorCodes: ignoreErrorCodes,
      );
      if (delay != null) {
        attempt++;
        await Future<void>.delayed(delay);
        continue;
      }
      _onProcessException(
        exception: e,
        platform: platform,
        failureMessage: failureMessage,
        posixPermissionSuggestion: posixPermissionSuggestion,
      );
      rethrow;
    }
  }
}

